__hydrateVak("vmbo","ma",{"A":{"sv":[{"v":"Wat is politiek?","o":["Een sport","Beslissingen nemen over de samenleving","Handel drijven","Een geloof"],"c":1,"d":1,"u":"Beslissen over de samenleving.","uo":["Nee, het juiste antwoord is «Beslissingen nemen over de samenleving».","Klopt: beslissen over de samenleving.","Nee, het juiste antwoord is «Beslissingen nemen over de samenleving».","Nee, het juiste antwoord is «Beslissingen nemen over de samenleving»."],"uh":"Beslissingen nemen over de samenleving: Beslissen over de samenleving."},{"v":"Waar legt links de nadruk op?","o":["Op vrijheid en de markt","Op een kleine overheid","Op gelijkheid","Op het geloof"],"c":2,"d":2,"u":"Links benadrukt gelijkheid.","uo":["Dat is rechts.","Dat is rechts.","Klopt: links benadrukt gelijkheid.","Nee, het juiste antwoord is «Op gelijkheid»."],"uh":"Op gelijkheid: Links benadrukt gelijkheid."},{"v":"Wat is een coalitie?","o":["Partijen die samen regeren","De controlerende partijen","Een belangengroep","Een verkiezing"],"c":0,"d":2,"u":"Partijen die samen regeren.","uo":["Klopt: partijen die samen regeren.","Dat is de oppositie.","Nee, het juiste antwoord is «Partijen die samen regeren».","Nee, het juiste antwoord is «Partijen die samen regeren»."],"uh":"Partijen die samen regeren."},{"v":"Wat doet de oppositie?","o":["Regeren","Wetten maken","Belasting innen","De regering controleren"],"c":3,"d":2,"u":"De oppositie controleert de regering.","uo":["Nee, dat doet de coalitie.","Nee, het juiste antwoord is «De regering controleren».","Nee, het juiste antwoord is «De regering controleren».","Klopt: de oppositie controleert de regering."],"uh":"De regering controleren: De oppositie controleert de regering."},{"v":"Waar staat het liberalisme voor?","o":["Gelijkheid","Vrijheid van het individu","Een geloof","Een sterke overheid"],"c":1,"d":2,"u":"Vrijheid van het individu.","uo":["Dat is socialisme.","Klopt: vrijheid van het individu.","Dat is confessioneel.","Nee, het juiste antwoord is «Vrijheid van het individu»."],"uh":"Vrijheid van het individu."},{"v":"Wat is lobbyen?","o":["Stemmen tellen","Regeren","Politici proberen te overtuigen","Een wet maken"],"c":2,"d":2,"u":"Politici proberen te beïnvloeden.","uo":["Nee, het juiste antwoord is «Politici proberen te overtuigen».","Nee, het juiste antwoord is «Politici proberen te overtuigen».","Klopt: politici proberen te beïnvloeden.","Nee, het juiste antwoord is «Politici proberen te overtuigen»."],"uh":"Politici proberen te beïnvloeden."},{"v":"Wat is een wetsvoorstel?","o":["Een voorstel voor een nieuwe wet","Een bestaande wet","Een verkiezing","Een straf"],"c":0,"d":1,"u":"Een voorstel voor een nieuwe wet.","uo":["Klopt: een voorstel voor een nieuwe wet.","Nee, het juiste antwoord is «Een voorstel voor een nieuwe wet».","Nee, het juiste antwoord is «Een voorstel voor een nieuwe wet».","Nee, het juiste antwoord is «Een voorstel voor een nieuwe wet»."],"uh":"Een voorstel voor een nieuwe wet."},{"v":"Waar staat het socialisme voor?","o":["Vrijheid van het individu","Een geloof","De vrije markt","Gelijkheid voor arbeiders"],"c":3,"d":2,"u":"Gelijkheid, opkomen voor arbeiders.","uo":["Dat is liberalisme.","Dat is confessioneel.","Nee, het juiste antwoord is «Gelijkheid voor arbeiders».","Klopt: gelijkheid, opkomen voor arbeiders."],"uh":"Gelijkheid, opkomen voor arbeiders."},{"v":"Wat gebeurt er bij verkiezingen?","o":["De regering wordt afgezet","Kiezers kiezen hun vertegenwoordigers","Wetten worden uitgevoerd","Belasting wordt geïnd"],"c":1,"d":2,"u":"Burgers kiezen vertegenwoordigers.","uo":["Niet per se.","Klopt: burgers kiezen vertegenwoordigers.","Nee, het juiste antwoord is «Kiezers kiezen hun vertegenwoordigers».","Nee, het juiste antwoord is «Kiezers kiezen hun vertegenwoordigers»."],"uh":"Kiezers kiezen hun vertegenwoordigers: Burgers kiezen vertegenwoordigers."},{"v":"Wat doet een belangengroep?","o":["Regeren","Rechtspreken","Opkomen voor een bepaald belang","Belasting innen"],"c":2,"d":2,"u":"Komt op voor een belang, zoals het milieu.","uo":["Nee, het juiste antwoord is «Opkomen voor een bepaald belang».","Nee, het juiste antwoord is «Opkomen voor een bepaald belang».","Klopt: komt op voor een belang, zoals het milieu.","Nee, het juiste antwoord is «Opkomen voor een bepaald belang»."],"uh":"Opkomen voor een bepaald belang: Komt op voor een belang, zoals het milieu."},{"v":"Wat staat er in een regeerakkoord?","o":["De afspraken van de coalitie","Een rechterlijk vonnis","De uitslag van verkiezingen","Een cao"],"c":0,"d":3,"u":"De plannen waarover de coalitie het eens is.","uo":["Klopt: de plannen waarover de coalitie het eens is.","Nee, het juiste antwoord is «De afspraken van de coalitie».","Nee, het juiste antwoord is «De afspraken van de coalitie».","Nee, het juiste antwoord is «De afspraken van de coalitie»."],"uh":"De afspraken van de coalitie: De plannen waarover de coalitie het eens is."}],"begrippen":[{"t":"Politiek","d":"het nemen van beslissingen over de samenleving"},{"t":"Politieke stroming","d":"een groep met gedeelde ideeën over de samenleving"},{"t":"Links","d":"de politieke richting met nadruk op gelijkheid en de overheid"},{"t":"Rechts","d":"de politieke richting met nadruk op vrijheid en de markt"},{"t":"Liberalisme","d":"een stroming die de vrijheid van het individu vooropstelt"},{"t":"Socialisme","d":"een stroming die opkomt voor gelijkheid en de arbeiders"},{"t":"Confessioneel","d":"politiek die uitgaat van een geloof"},{"t":"Wetsvoorstel","d":"een voorstel voor een nieuwe wet"},{"t":"Coalitie","d":"een samenwerking van partijen die samen regeren"},{"t":"Oppositie","d":"de partijen die niet meeregeren en de regering controleren"},{"t":"Belangengroep","d":"een groep die opkomt voor een bepaald belang"},{"t":"Lobbyen","d":"het proberen te beïnvloeden van politici"},{"t":"Verkiezingen","d":"de manier waarop kiezers hun vertegenwoordigers kiezen"},{"t":"Regeerakkoord","d":"de afspraken van de partijen die samen gaan regeren"}],"sam":"<div class=\"sam-intro\">In de <strong>politiek</strong> worden beslissingen over de samenleving genomen. <strong>Politieke stromingen</strong> lopen van <strong>links</strong> (gelijkheid) tot <strong>rechts</strong> (vrijheid). De regerende partijen vormen een <strong>coalitie</strong>, de rest de <strong>oppositie</strong>.</div><div class=\"sam-head\">1. Politieke stromingen</div><p><strong>Politiek</strong> gaat over het nemen van beslissingen voor de samenleving. Partijen horen bij een <strong>politieke stroming</strong>. Grofweg legt <strong>links</strong> de nadruk op gelijkheid en een sturende overheid, en <strong>rechts</strong> op vrijheid en de markt. Belangrijke stromingen zijn het <strong>liberalisme</strong> (vrijheid van het individu), het <strong>socialisme</strong> (gelijkheid) en het <strong>confessioneel</strong>e denken (op basis van een geloof).</p><div class=\"sam-head\">2. Van wetsvoorstel tot beleid</div><p>Een nieuwe wet begint als <strong>wetsvoorstel</strong> en wordt door het parlement behandeld. De partijen die samen regeren vormen een <strong>coalitie</strong> en leggen hun plannen vast in een <strong>regeerakkoord</strong>; de <strong>oppositie</strong> controleert hen. Bij <strong>verkiezingen</strong> kiezen burgers hun vertegenwoordigers.</p><div class=\"sam-head\">3. Invloed uitoefenen</div><p>Burgers en organisaties kunnen invloed uitoefenen. Een <strong>belangengroep</strong> komt op voor een bepaald belang, bijvoorbeeld het milieu. Door te <strong>lobbyen</strong> proberen zij politici te overtuigen.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Politiek</div><div class=\"sam-definitie-body\">het nemen van beslissingen over de samenleving.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Politieke stroming</div><div class=\"sam-definitie-body\">een groep met gedeelde ideeën over de samenleving.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Links</div><div class=\"sam-definitie-body\">de politieke richting met nadruk op gelijkheid en de overheid.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Rechts</div><div class=\"sam-definitie-body\">de politieke richting met nadruk op vrijheid en de markt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Liberalisme</div><div class=\"sam-definitie-body\">een stroming die de vrijheid van het individu vooropstelt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Socialisme</div><div class=\"sam-definitie-body\">een stroming die opkomt voor gelijkheid en de arbeiders.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Confessioneel</div><div class=\"sam-definitie-body\">politiek die uitgaat van een geloof.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Wetsvoorstel</div><div class=\"sam-definitie-body\">een voorstel voor een nieuwe wet.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Coalitie</div><div class=\"sam-definitie-body\">een samenwerking van partijen die samen regeren.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Oppositie</div><div class=\"sam-definitie-body\">de partijen die niet meeregeren en de regering controleren.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Belangengroep</div><div class=\"sam-definitie-body\">een groep die opkomt voor een bepaald belang.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Lobbyen</div><div class=\"sam-definitie-body\">het proberen te beïnvloeden van politici.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Verkiezingen</div><div class=\"sam-definitie-body\">de manier waarop kiezers hun vertegenwoordigers kiezen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Regeerakkoord</div><div class=\"sam-definitie-body\">de afspraken van de partijen die samen gaan regeren.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Politiek»</b> is beslissen over de samenleving, terwijl <b>«Politieke stroming»</b> groep met gedeelde ideeën is. <b>«Links»</b> is nadruk op gelijkheid, terwijl <b>«Rechts»</b> nadruk op vrijheid is. <b>«Liberalisme»</b> is vrijheid van het individu, terwijl <b>«Socialisme»</b> gelijkheid voor arbeiders is. <b>«Confessioneel»</b> is politiek op basis van geloof, terwijl <b>«Liberalisme»</b> vrijheid van het individu is.</div>"},"B":{"sv":[{"v":"Wat is de arbeidsmarkt?","o":["Een winkelstraat","Vraag naar en aanbod van werk","Een fabriek","Een vakbond"],"c":1,"d":2,"u":"Waar vraag en aanbod van werk samenkomen.","uo":["Nee, het juiste antwoord is «Vraag naar en aanbod van werk».","Klopt: waar vraag en aanbod van werk samenkomen.","Nee, het juiste antwoord is «Vraag naar en aanbod van werk».","Nee, het juiste antwoord is «Vraag naar en aanbod van werk»."],"uh":"Vraag naar en aanbod van werk: Waar vraag en aanbod van werk samenkomen."},{"v":"Wat is werkloosheid?","o":["Veel banen","Een hoog loon","Mensen hebben geen werk","Een staking"],"c":2,"d":1,"u":"Mensen zonder werk.","uo":["Juist niet, het juiste antwoord is «Mensen hebben geen werk».","Nee, het juiste antwoord is «Mensen hebben geen werk».","Klopt: mensen zonder werk.","Nee, het juiste antwoord is «Mensen hebben geen werk»."],"uh":"Mensen hebben geen werk: Mensen zonder werk."},{"v":"Wat doet een werkgever?","o":["Neemt mensen in dienst","Werkt in loondienst","Betaalt uitkeringen","Staakt"],"c":0,"d":1,"u":"Neemt mensen aan.","uo":["Klopt: neemt mensen aan.","Dat is de werknemer.","Nee, het juiste antwoord is «Neemt mensen in dienst».","Nee, het juiste antwoord is «Neemt mensen in dienst»."],"uh":"Neemt mensen aan."},{"v":"Wat doet een vakbond?","o":["Winst maken","Regeren","Belasting innen","Opkomen voor werknemers"],"c":3,"d":2,"u":"Komt op voor werknemers.","uo":["Nee, het juiste antwoord is «Opkomen voor werknemers».","Nee, het juiste antwoord is «Opkomen voor werknemers».","Nee, het juiste antwoord is «Opkomen voor werknemers».","Klopt: komt op voor werknemers."],"uh":"Opkomen voor werknemers: Komt op voor werknemers."},{"v":"Wat is een cao?","o":["Een uitkering","Afspraken over arbeidsvoorwaarden","Een belasting","Een staking"],"c":1,"d":2,"u":"Afspraken over het werk voor een bedrijfstak.","uo":["Nee, het juiste antwoord is «Afspraken over arbeidsvoorwaarden».","Klopt: afspraken over het werk voor een bedrijfstak.","Nee, het juiste antwoord is «Afspraken over arbeidsvoorwaarden».","Nee, het juiste antwoord is «Afspraken over arbeidsvoorwaarden»."],"uh":"Afspraken over het werk voor een bedrijfstak."},{"v":"Wat is het minimumloon?","o":["Het hoogste loon","Een uitkering","Het wettelijk laagste loon","Winst"],"c":2,"d":2,"u":"Het laagste loon dat betaald mag worden.","uo":["Juist niet, het juiste antwoord is «Het wettelijk laagste loon».","Nee, het juiste antwoord is «Het wettelijk laagste loon».","Klopt: het laagste loon dat betaald mag worden.","Nee, het juiste antwoord is «Het wettelijk laagste loon»."],"uh":"Het wettelijk laagste loon: Het laagste loon dat betaald mag worden."},{"v":"Wat is een uitkering?","o":["Geld van de overheid bij te weinig inkomen","Loon uit werk","Winst van een bedrijf","Een cao"],"c":0,"d":2,"u":"Geld voor wie niet genoeg inkomen heeft.","uo":["Klopt: geld voor wie niet genoeg inkomen heeft.","Dat is inkomen.","Nee, het juiste antwoord is «Geld van de overheid bij te weinig inkomen».","Nee, het juiste antwoord is «Geld van de overheid bij te weinig inkomen»."],"uh":"Geld van de overheid bij te weinig inkomen: Geld voor wie niet genoeg inkomen heeft."},{"v":"Wat is een staking?","o":["Ontslag","Een uitkering","Een cao","Het werk neerleggen om eisen"],"c":3,"d":2,"u":"Werknemers leggen het werk neer.","uo":["Nee, het juiste antwoord is «Het werk neerleggen om eisen».","Nee, het juiste antwoord is «Het werk neerleggen om eisen».","Nee, het juiste antwoord is «Het werk neerleggen om eisen».","Klopt: werknemers leggen het werk neer."],"uh":"Het werk neerleggen om eisen: Werknemers leggen het werk neer."},{"v":"Wat doet een werknemer?","o":["Neemt mensen aan","Werkt in loondienst","Int belasting","Maakt de wet"],"c":1,"d":1,"u":"Werkt in loondienst.","uo":["Dat is de werkgever.","Klopt: werkt in loondienst.","Nee, het juiste antwoord is «Werkt in loondienst».","Nee, het juiste antwoord is «Werkt in loondienst»."],"uh":"Werkt in loondienst."},{"v":"Wat is werkgelegenheid?","o":["Een uitkering","Een staking","De hoeveelheid beschikbaar werk","Een vakbond"],"c":2,"d":2,"u":"Hoeveel werk er is.","uo":["Nee, het juiste antwoord is «De hoeveelheid beschikbaar werk».","Nee, het juiste antwoord is «De hoeveelheid beschikbaar werk».","Klopt: hoeveel werk er is.","Nee, het juiste antwoord is «De hoeveelheid beschikbaar werk»."],"uh":"De hoeveelheid beschikbaar werk: Hoeveel werk er is."},{"v":"Wat is sociale zekerheid?","o":["Een stelsel dat inkomen geeft bij tegenslag","Loon uit werk","Een belasting","Een cao"],"c":0,"d":3,"u":"Vangt je op met een uitkering bij tegenslag.","uo":["Klopt: vangt je op met een uitkering bij tegenslag.","Nee, het juiste antwoord is «Een stelsel dat inkomen geeft bij tegenslag».","Nee, het juiste antwoord is «Een stelsel dat inkomen geeft bij tegenslag».","Nee, het juiste antwoord is «Een stelsel dat inkomen geeft bij tegenslag»."],"uh":"Een stelsel dat inkomen geeft bij tegenslag: Vangt je op met een uitkering bij tegenslag."}],"begrippen":[{"t":"Werkgelegenheid","d":"de hoeveelheid beschikbaar werk"},{"t":"Werkloosheid","d":"de situatie waarin mensen geen werk hebben"},{"t":"Werkgever","d":"iemand of een bedrijf dat mensen in dienst neemt"},{"t":"Werknemer","d":"iemand die in loondienst werkt"},{"t":"Vakbond","d":"een organisatie die opkomt voor werknemers"},{"t":"Cao","d":"afspraken over arbeidsvoorwaarden voor een hele bedrijfstak"},{"t":"Inkomen","d":"het geld dat je ontvangt, zoals loon"},{"t":"Sociale zekerheid","d":"het stelsel dat inkomen geeft bij tegenslag"},{"t":"Uitkering","d":"geld van de overheid voor wie niet genoeg inkomen heeft"},{"t":"Minimumloon","d":"het wettelijk laagste loon dat betaald mag worden"},{"t":"Arbeidsmarkt","d":"het geheel van vraag naar en aanbod van werk"},{"t":"Staking","d":"het neerleggen van het werk om eisen kracht bij te zetten"}],"sam":"<div class=\"sam-intro\">Op de <strong>arbeidsmarkt</strong> ontmoeten vraag en aanbod van werk elkaar. <strong>Werkgevers</strong> en <strong>werknemers</strong> maken via <strong>vakbonden</strong> een <strong>cao</strong>. Wie geen werk heeft, kent <strong>werkloosheid</strong>.</div><div class=\"sam-head\">1. De arbeidsmarkt</div><p>De <strong>arbeidsmarkt</strong> is het geheel van vraag naar en aanbod van werk. De hoeveelheid beschikbaar werk heet de <strong>werkgelegenheid</strong>; is er te weinig, dan ontstaat <strong>werkloosheid</strong>. Een <strong>werkgever</strong> neemt mensen aan, een <strong>werknemer</strong> werkt in loondienst.</p><div class=\"sam-head\">2. Afspraken en zekerheid</div><p>Over het werk worden afspraken gemaakt. Een <strong>vakbond</strong> komt op voor werknemers en onderhandelt over een <strong>cao</strong>; het <strong>minimumloon</strong> is het wettelijk laagste loon. Soms leggen werknemers het werk neer: een <strong>staking</strong>. Wie zijn baan verliest, valt terug op de <strong>sociale zekerheid</strong> met een <strong>uitkering</strong> in plaats van <strong>inkomen</strong> uit werk.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Werkgelegenheid</div><div class=\"sam-definitie-body\">de hoeveelheid beschikbaar werk.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Werkloosheid</div><div class=\"sam-definitie-body\">de situatie waarin mensen geen werk hebben.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Werkgever</div><div class=\"sam-definitie-body\">iemand of een bedrijf dat mensen in dienst neemt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Werknemer</div><div class=\"sam-definitie-body\">iemand die in loondienst werkt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vakbond</div><div class=\"sam-definitie-body\">een organisatie die opkomt voor werknemers.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Cao</div><div class=\"sam-definitie-body\">afspraken over arbeidsvoorwaarden voor een hele bedrijfstak.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Inkomen</div><div class=\"sam-definitie-body\">het geld dat je ontvangt, zoals loon.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Sociale zekerheid</div><div class=\"sam-definitie-body\">het stelsel dat inkomen geeft bij tegenslag.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Uitkering</div><div class=\"sam-definitie-body\">geld van de overheid voor wie niet genoeg inkomen heeft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Minimumloon</div><div class=\"sam-definitie-body\">het wettelijk laagste loon dat betaald mag worden.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Arbeidsmarkt</div><div class=\"sam-definitie-body\">het geheel van vraag naar en aanbod van werk.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Staking</div><div class=\"sam-definitie-body\">het neerleggen van het werk om eisen kracht bij te zetten.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Werkgelegenheid»</b> is hoeveelheid werk, terwijl <b>«Werkloosheid»</b> geen werk hebben is. <b>«Werkgever»</b> is neemt mensen aan, terwijl <b>«Werknemer»</b> werkt in loondienst is. <b>«Vakbond»</b> is komt op voor werknemers, terwijl <b>«Cao»</b> afspraken over het werk is. <b>«Inkomen»</b> is geld dat je ontvangt, terwijl <b>«Uitkering»</b> geld bij te weinig inkomen is.</div>"},"C":{"sv":[{"v":"Wat is een multiculturele samenleving?","o":["Een samenleving met één cultuur","Een samenleving met veel culturen","Een land zonder migranten","Een geloof"],"c":1,"d":1,"u":"Mensen van veel culturen samen.","uo":["Juist niet, het juiste antwoord is «Een samenleving met veel culturen».","Klopt: mensen van veel culturen samen.","Nee, het juiste antwoord is «Een samenleving met veel culturen».","Nee, het juiste antwoord is «Een samenleving met veel culturen»."],"uh":"Een samenleving met veel culturen: Mensen van veel culturen samen."},{"v":"Wat is integratie?","o":["Gescheiden leven","Vertrekken uit een land","Meedoen in de samenleving","Discrimineren"],"c":2,"d":2,"u":"Nieuwkomers doen mee.","uo":["Dat is segregatie.","Nee, het juiste antwoord is «Meedoen in de samenleving».","Klopt: nieuwkomers doen mee.","Nee, het juiste antwoord is «Meedoen in de samenleving»."],"uh":"Meedoen in de samenleving: Nieuwkomers doen mee."},{"v":"Wat is discriminatie?","o":["Mensen ongelijk behandelen om wie ze zijn","Iedereen gelijk behandelen","Verhuizen","Een geloof kiezen"],"c":0,"d":2,"u":"Ongelijke behandeling om wie iemand is.","uo":["Klopt: ongelijke behandeling om wie iemand is.","Juist het tegenovergestelde.","Nee, het juiste antwoord is «Mensen ongelijk behandelen om wie ze zijn».","Nee, het juiste antwoord is «Mensen ongelijk behandelen om wie ze zijn»."],"uh":"Mensen ongelijk behandelen om wie ze zijn: Ongelijke behandeling om wie iemand is."},{"v":"Wat is een vooroordeel?","o":["Een bewezen feit","Een wet","Een straf","Een mening zonder de feiten te kennen"],"c":3,"d":2,"u":"Een oordeel vooraf, zonder feiten.","uo":["Nee, het juiste antwoord is «Een mening zonder de feiten te kennen».","Nee, het juiste antwoord is «Een mening zonder de feiten te kennen».","Nee, het juiste antwoord is «Een mening zonder de feiten te kennen».","Klopt: een oordeel vooraf, zonder feiten."],"uh":"Een mening zonder de feiten te kennen: Een oordeel vooraf, zonder feiten."},{"v":"Wat is segregatie?","o":["Samen opgaan","Groepen leven gescheiden","Gelijke kansen","Een geloof"],"c":1,"d":2,"u":"Bevolkingsgroepen leven gescheiden.","uo":["Dat is integratie.","Klopt: bevolkingsgroepen leven gescheiden.","Nee, het juiste antwoord is «Groepen leven gescheiden».","Nee, het juiste antwoord is «Groepen leven gescheiden»."],"uh":"Groepen leven gescheiden: Bevolkingsgroepen leven gescheiden."},{"v":"Wat is een stereotype?","o":["Een bewijs","Een wet","Een vast beeld van een groep","Een migrant"],"c":2,"d":2,"u":"Een vast, vaak overdreven beeld van een groep.","uo":["Nee, het juiste antwoord is «Een vast beeld van een groep».","Nee, het juiste antwoord is «Een vast beeld van een groep».","Klopt: een vast, vaak overdreven beeld van een groep.","Nee, het juiste antwoord is «Een vast beeld van een groep»."],"uh":"Een vast beeld van een groep: Een vast, vaak overdreven beeld van een groep."},{"v":"Wat is godsdienstvrijheid?","o":["Het recht je eigen geloof te kiezen","Verplicht geloven","Geen geloof toestaan","Een cultuur"],"c":0,"d":2,"u":"Iedereen mag zijn eigen geloof kiezen.","uo":["Klopt: iedereen mag zijn eigen geloof kiezen.","Nee, het juiste antwoord is «Het recht je eigen geloof te kiezen».","Nee, het juiste antwoord is «Het recht je eigen geloof te kiezen».","Nee, het juiste antwoord is «Het recht je eigen geloof te kiezen»."],"uh":"Het recht je eigen geloof te kiezen: Iedereen mag zijn eigen geloof kiezen."},{"v":"Wat is emancipatie?","o":["Discriminatie","Segregatie","Een vooroordeel","Streven naar gelijke rechten"],"c":3,"d":3,"u":"Streven naar gelijke rechten en kansen.","uo":["Nee, het juiste antwoord is «Streven naar gelijke rechten».","Nee, het juiste antwoord is «Streven naar gelijke rechten».","Nee, het juiste antwoord is «Streven naar gelijke rechten».","Klopt: streven naar gelijke rechten en kansen."],"uh":"Streven naar gelijke rechten en kansen."},{"v":"Wat is een migrant?","o":["Iemand die nooit verhuist","Iemand die naar een ander land verhuist","Een rechter","Een politicus"],"c":1,"d":1,"u":"Iemand die naar een ander land verhuist.","uo":["Nee, het juiste antwoord is «Iemand die naar een ander land verhuist».","Klopt: iemand die naar een ander land verhuist.","Nee, het juiste antwoord is «Iemand die naar een ander land verhuist».","Nee, het juiste antwoord is «Iemand die naar een ander land verhuist»."],"uh":"Iemand die naar een ander land verhuist."},{"v":"Wat is tolerantie?","o":["Discrimineren","Uitsluiten","Andere culturen en meningen verdragen","Verhuizen"],"c":2,"d":2,"u":"Anderen en hun mening verdragen.","uo":["Juist niet, het juiste antwoord is «Andere culturen en meningen verdragen».","Nee, het juiste antwoord is «Andere culturen en meningen verdragen».","Klopt: anderen en hun mening verdragen.","Nee, het juiste antwoord is «Andere culturen en meningen verdragen»."],"uh":"Andere culturen en meningen verdragen: Anderen en hun mening verdragen."},{"v":"Wat hoort bij cultuur?","o":["Taal, gewoonten en gebruiken","Alleen geld","Alleen wetten","Alleen het weer"],"c":0,"d":1,"u":"Taal, gewoonten en gebruiken van een groep.","uo":["Klopt: taal, gewoonten en gebruiken van een groep.","Nee, het juiste antwoord is «Taal, gewoonten en gebruiken».","Nee, het juiste antwoord is «Taal, gewoonten en gebruiken».","Nee, het juiste antwoord is «Taal, gewoonten en gebruiken»."],"uh":"Taal, gewoonten en gebruiken van een groep."}],"begrippen":[{"t":"Multiculturele samenleving","d":"een samenleving met mensen van veel culturen"},{"t":"Cultuur","d":"de gewoonten, taal en gebruiken van een groep"},{"t":"Identiteit","d":"het gevoel bij een groep te horen"},{"t":"Integratie","d":"het opgaan van migranten in de samenleving"},{"t":"Discriminatie","d":"het ongelijk behandelen van mensen om wie ze zijn"},{"t":"Vooroordeel","d":"een mening vooraf, zonder de feiten te kennen"},{"t":"Stereotype","d":"een vast, vaak overdreven beeld van een groep"},{"t":"Tolerantie","d":"het verdragen van andere culturen en meningen"},{"t":"Migrant","d":"iemand die naar een ander land verhuist"},{"t":"Segregatie","d":"het gescheiden leven van bevolkingsgroepen"},{"t":"Emancipatie","d":"het streven naar gelijke rechten en kansen"},{"t":"Godsdienstvrijheid","d":"het recht om je eigen geloof te kiezen"}],"sam":"<div class=\"sam-intro\">In een <strong>multiculturele samenleving</strong> leven mensen van veel <strong>culturen</strong> samen. <strong>Integratie</strong> is het meedoen van migranten; het tegenovergestelde is <strong>segregatie</strong>. <strong>Discriminatie</strong> en <strong>vooroordelen</strong> staan gelijke behandeling in de weg.</div><div class=\"sam-head\">1. Cultuur en identiteit</div><p>In een <strong>multiculturele samenleving</strong> wonen mensen met verschillende achtergronden samen. Hun <strong>cultuur</strong> (taal, gewoonten, gebruiken) en hun <strong>identiteit</strong> (het gevoel ergens bij te horen) verschillen. De <strong>godsdienstvrijheid</strong> geeft iedereen het recht op een eigen geloof. Een <strong>migrant</strong> is iemand die naar een ander land verhuist.</p><div class=\"sam-head\">2. Samenleven: kansen en spanningen</div><p><strong>Integratie</strong> is het meedoen van nieuwkomers; blijven groepen juist gescheiden, dan is er <strong>segregatie</strong>. <strong>Discriminatie</strong> is het ongelijk behandelen van mensen om wie ze zijn, vaak gevoed door een <strong>vooroordeel</strong> of een <strong>stereotype</strong> (een vast beeld van een groep). <strong>Tolerantie</strong> en <strong>emancipatie</strong> helpen om gelijke kansen te bereiken.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Multiculturele samenleving</div><div class=\"sam-definitie-body\">een samenleving met mensen van veel culturen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Cultuur</div><div class=\"sam-definitie-body\">de gewoonten, taal en gebruiken van een groep.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Identiteit</div><div class=\"sam-definitie-body\">het gevoel bij een groep te horen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Integratie</div><div class=\"sam-definitie-body\">het opgaan van migranten in de samenleving.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Discriminatie</div><div class=\"sam-definitie-body\">het ongelijk behandelen van mensen om wie ze zijn.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Vooroordeel</div><div class=\"sam-definitie-body\">een mening vooraf, zonder de feiten te kennen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Stereotype</div><div class=\"sam-definitie-body\">een vast, vaak overdreven beeld van een groep.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Tolerantie</div><div class=\"sam-definitie-body\">het verdragen van andere culturen en meningen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Migrant</div><div class=\"sam-definitie-body\">iemand die naar een ander land verhuist.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Segregatie</div><div class=\"sam-definitie-body\">het gescheiden leven van bevolkingsgroepen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Emancipatie</div><div class=\"sam-definitie-body\">het streven naar gelijke rechten en kansen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Godsdienstvrijheid</div><div class=\"sam-definitie-body\">het recht om je eigen geloof te kiezen.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Multiculturele samenleving»</b> is veel culturen samen, terwijl <b>«Cultuur»</b> gewoonten en gebruiken is. <b>«Cultuur»</b> is gewoonten en gebruiken, terwijl <b>«Identiteit»</b> gevoel van erbij horen is. <b>«Integratie»</b> is meedoen in de samenleving, terwijl <b>«Segregatie»</b> gescheiden leven is. <b>«Discriminatie»</b> is ongelijk behandelen, terwijl <b>«Vooroordeel»</b> oordeel zonder feiten is.</div>"},"D":{"sv":[{"v":"Wat is een rechtsstaat?","o":["Een land zonder wetten","Een staat waarin de wet voor iedereen geldt","Een gevangenis","Een rechtszaak"],"c":1,"d":2,"u":"Iedereen houdt zich aan de wet en heeft rechten.","uo":["Juist niet, het juiste antwoord is «Een staat waarin de wet voor iedereen geldt».","Klopt: iedereen houdt zich aan de wet en heeft rechten.","Nee, het juiste antwoord is «Een staat waarin de wet voor iedereen geldt».","Nee, het juiste antwoord is «Een staat waarin de wet voor iedereen geldt»."],"uh":"Een staat waarin de wet voor iedereen geldt: Iedereen houdt zich aan de wet en heeft rechten."},{"v":"Wat is een misdrijf?","o":["Te hard rijden","Een lichte fout","Een ernstig strafbaar feit","Een boete"],"c":2,"d":2,"u":"Een ernstig strafbaar feit zoals diefstal.","uo":["Dat is een overtreding.","Nee, het juiste antwoord is «Een ernstig strafbaar feit».","Klopt: een ernstig strafbaar feit zoals diefstal.","Nee, het juiste antwoord is «Een ernstig strafbaar feit»."],"uh":"Een ernstig strafbaar feit zoals diefstal."},{"v":"Wat is een overtreding?","o":["Een licht strafbaar feit","Een zware misdaad","Een straf","Een rechter"],"c":0,"d":2,"u":"Een licht feit, zoals te hard rijden.","uo":["Klopt: een licht feit, zoals te hard rijden.","Dat is een misdrijf.","Nee, het juiste antwoord is «Een licht strafbaar feit».","Nee, het juiste antwoord is «Een licht strafbaar feit»."],"uh":"Een licht feit, zoals te hard rijden."},{"v":"Wat doet de rechter?","o":["Aanklagen","Verdedigen","De verdachte zijn","Een oordeel vellen"],"c":3,"d":2,"u":"Velt het oordeel en bepaalt de straf.","uo":["Dat doet de officier van justitie.","Dat doet de advocaat.","Nee, het juiste antwoord is «Een oordeel vellen».","Klopt: velt het oordeel en bepaalt de straf."],"uh":"Een oordeel vellen: Velt het oordeel en bepaalt de straf."},{"v":"Wat doet de officier van justitie?","o":["Verdedigt de verdachte","Klaagt aan namens de staat","Velt het oordeel","Is de verdachte"],"c":1,"d":2,"u":"De aanklager namens de staat.","uo":["Dat doet de advocaat.","Klopt: de aanklager namens de staat.","Dat doet de rechter.","Nee, het juiste antwoord is «Klaagt aan namens de staat»."],"uh":"Klaagt aan namens de staat: De aanklager namens de staat."},{"v":"Wat betekent de onschuldpresumptie?","o":["Je bent altijd schuldig","De rechter beslist vooraf","Je bent onschuldig tot het tegendeel bewezen is","Er is geen advocaat nodig"],"c":2,"d":3,"u":"Onschuldig tot schuld bewezen is.","uo":["Juist niet, het juiste antwoord is «Je bent onschuldig tot het tegendeel bewezen is».","Nee, het juiste antwoord is «Je bent onschuldig tot het tegendeel bewezen is».","Klopt: onschuldig tot schuld bewezen is.","Nee, het juiste antwoord is «Je bent onschuldig tot het tegendeel bewezen is»."],"uh":"Je bent onschuldig tot het tegendeel bewezen is: Onschuldig tot schuld bewezen is."},{"v":"Wat is preventie?","o":["Criminaliteit voorkomen","Straffen","Opnieuw de fout in gaan","Aanklagen"],"c":0,"d":1,"u":"Criminaliteit voorkomen.","uo":["Klopt: criminaliteit voorkomen.","Nee, het juiste antwoord is «Criminaliteit voorkomen».","Dat is recidive.","Nee, het juiste antwoord is «Criminaliteit voorkomen»."],"uh":"Criminaliteit voorkomen."},{"v":"Wat is recidive?","o":["Voorkomen","Een taakstraf","Bewijs","Opnieuw een strafbaar feit plegen"],"c":3,"d":3,"u":"Opnieuw de fout in gaan.","uo":["Dat is preventie.","Nee, het juiste antwoord is «Opnieuw een strafbaar feit plegen».","Nee, het juiste antwoord is «Opnieuw een strafbaar feit plegen».","Klopt: opnieuw de fout in gaan."],"uh":"Opnieuw een strafbaar feit plegen: Opnieuw de fout in gaan."},{"v":"Wat doet een advocaat?","o":["Klaagt aan","Verdedigt de verdachte","Velt het vonnis","Int de boete"],"c":1,"d":1,"u":"Verdedigt de verdachte.","uo":["Dat doet de officier.","Klopt: verdedigt de verdachte.","Dat doet de rechter.","Nee, het juiste antwoord is «Verdedigt de verdachte»."],"uh":"Verdedigt de verdachte."},{"v":"Wat is een taakstraf?","o":["Een boete","Gevangenis","Onbetaald werk als straf","Een waarschuwing"],"c":2,"d":2,"u":"Je moet onbetaald werk doen.","uo":["Nee, het juiste antwoord is «Onbetaald werk als straf».","Nee, het juiste antwoord is «Onbetaald werk als straf».","Klopt: je moet onbetaald werk doen.","Nee, het juiste antwoord is «Onbetaald werk als straf»."],"uh":"Onbetaald werk als straf: Je moet onbetaald werk doen."},{"v":"Wat is bewijs in een strafproces?","o":["Gegevens die aantonen of iemand iets deed","Een straf","Een mening","Een boete"],"c":0,"d":2,"u":"Gegevens die schuld of onschuld aantonen.","uo":["Klopt: gegevens die schuld of onschuld aantonen.","Nee, het juiste antwoord is «Gegevens die aantonen of iemand iets deed».","Nee, het juiste antwoord is «Gegevens die aantonen of iemand iets deed».","Nee, het juiste antwoord is «Gegevens die aantonen of iemand iets deed»."],"uh":"Gegevens die schuld of onschuld aantonen."}],"begrippen":[{"t":"Criminaliteit","d":"gedrag dat bij de wet verboden is"},{"t":"Rechtsstaat","d":"een staat waarin iedereen zich aan de wet houdt en rechten heeft"},{"t":"Misdrijf","d":"een ernstig strafbaar feit, zoals diefstal of geweld"},{"t":"Overtreding","d":"een licht strafbaar feit, zoals te hard rijden"},{"t":"Verdachte","d":"iemand die van een strafbaar feit wordt beschuldigd"},{"t":"Officier van justitie","d":"de aanklager namens de staat"},{"t":"Rechter","d":"degene die een oordeel velt en de straf bepaalt"},{"t":"Advocaat","d":"iemand die een verdachte verdedigt"},{"t":"Strafproces","d":"de rechtszaak waarin over schuld en straf wordt beslist"},{"t":"Bewijs","d":"gegevens die aantonen of iemand iets heeft gedaan"},{"t":"Preventie","d":"het voorkomen van criminaliteit"},{"t":"Recidive","d":"het opnieuw plegen van een strafbaar feit"},{"t":"Taakstraf","d":"een straf waarbij je onbetaald werk moet doen"},{"t":"Onschuldpresumptie","d":"je bent onschuldig tot het tegendeel bewezen is"}],"sam":"<div class=\"sam-intro\">In een <strong>rechtsstaat</strong> gelden voor iedereen dezelfde regels en rechten. <strong>Criminaliteit</strong> bestaat uit <strong>misdrijven</strong> en <strong>overtredingen</strong>. In een <strong>strafproces</strong> beslist de <strong>rechter</strong> over schuld en straf.</div><div class=\"sam-head\">1. Criminaliteit in de rechtsstaat</div><p>Een <strong>rechtsstaat</strong> is een staat waarin iedereen zich aan de wet houdt en rechten heeft. <strong>Criminaliteit</strong> is gedrag dat verboden is. Een <strong>misdrijf</strong> is ernstig (diefstal, geweld), een <strong>overtreding</strong> licht (te hard rijden). De overheid probeert criminaliteit te voorkomen met <strong>preventie</strong> en wil <strong>recidive</strong> (opnieuw de fout in gaan) tegengaan.</p><div class=\"sam-head\">2. Het strafproces</div><p>Wordt iemand verdacht, dan volgt een <strong>strafproces</strong>. De <strong>officier van justitie</strong> klaagt aan namens de staat, de <strong>advocaat</strong> verdedigt de <strong>verdachte</strong> en de <strong>rechter</strong> velt het oordeel op basis van <strong>bewijs</strong>. Daarbij geldt de <strong>onschuldpresumptie</strong>: je bent onschuldig tot het tegendeel bewezen is. Een mogelijke straf is een <strong>taakstraf</strong>.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Criminaliteit</div><div class=\"sam-definitie-body\">gedrag dat bij de wet verboden is.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Rechtsstaat</div><div class=\"sam-definitie-body\">een staat waarin iedereen zich aan de wet houdt en rechten heeft.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Misdrijf</div><div class=\"sam-definitie-body\">een ernstig strafbaar feit, zoals diefstal of geweld.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Overtreding</div><div class=\"sam-definitie-body\">een licht strafbaar feit, zoals te hard rijden.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Verdachte</div><div class=\"sam-definitie-body\">iemand die van een strafbaar feit wordt beschuldigd.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Officier van justitie</div><div class=\"sam-definitie-body\">de aanklager namens de staat.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Rechter</div><div class=\"sam-definitie-body\">degene die een oordeel velt en de straf bepaalt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Advocaat</div><div class=\"sam-definitie-body\">iemand die een verdachte verdedigt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Strafproces</div><div class=\"sam-definitie-body\">de rechtszaak waarin over schuld en straf wordt beslist.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Bewijs</div><div class=\"sam-definitie-body\">gegevens die aantonen of iemand iets heeft gedaan.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Preventie</div><div class=\"sam-definitie-body\">het voorkomen van criminaliteit.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Recidive</div><div class=\"sam-definitie-body\">het opnieuw plegen van een strafbaar feit.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Taakstraf</div><div class=\"sam-definitie-body\">een straf waarbij je onbetaald werk moet doen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Onschuldpresumptie</div><div class=\"sam-definitie-body\">je bent onschuldig tot het tegendeel bewezen is.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Criminaliteit»</b> is verboden gedrag, terwijl <b>«Misdrijf»</b> ernstig strafbaar feit is. <b>«Misdrijf»</b> is ernstig strafbaar feit, terwijl <b>«Overtreding»</b> licht strafbaar feit is. <b>«Verdachte»</b> is wordt beschuldigd, terwijl <b>«Advocaat»</b> verdedigt de verdachte is. <b>«Officier van justitie»</b> is de aanklager, terwijl <b>«Rechter»</b> velt het oordeel is.</div>"},"E":{"sv":[{"v":"Wat zijn massamedia?","o":["Media voor één persoon","Media die veel mensen tegelijk bereiken","Een reclamebord","Een oude krant"],"c":1,"d":1,"u":"Bereiken veel mensen tegelijk.","uo":["Juist niet, het juiste antwoord is «Media die veel mensen tegelijk bereiken».","Klopt: bereiken veel mensen tegelijk.","Nee, het juiste antwoord is «Media die veel mensen tegelijk bereiken».","Nee, het juiste antwoord is «Media die veel mensen tegelijk bereiken»."],"uh":"Media die veel mensen tegelijk bereiken: Bereiken veel mensen tegelijk."},{"v":"Wat is de informerende functie?","o":["Vermaken","Meningen geven","Nieuws en informatie geven","Reclame maken"],"c":2,"d":2,"u":"Nieuws en informatie geven.","uo":["Dat is amuseren.","Dat is opiniëren.","Klopt: nieuws en informatie geven.","Nee, het juiste antwoord is «Nieuws en informatie geven»."],"uh":"Nieuws en informatie geven."},{"v":"Wat is de amuserende functie?","o":["Het publiek vermaken","Nieuws geven","Meningen geven","Censureren"],"c":0,"d":2,"u":"Het publiek vermaken.","uo":["Klopt: het publiek vermaken.","Dat is informeren.","Dat is opiniëren.","Nee, het juiste antwoord is «Het publiek vermaken»."],"uh":"Het publiek vermaken."},{"v":"Wat is persvrijheid?","o":["Censuur","Nepnieuws","Reclame","Het recht van media om vrij te publiceren"],"c":3,"d":2,"u":"Media mogen vrij publiceren.","uo":["Juist het tegenovergestelde.","Nee, het juiste antwoord is «Het recht van media om vrij te publiceren».","Nee, het juiste antwoord is «Het recht van media om vrij te publiceren».","Klopt: media mogen vrij publiceren."],"uh":"Het recht van media om vrij te publiceren: Media mogen vrij publiceren."},{"v":"Wat is censuur?","o":["Vrij publiceren","Informatie tegenhouden of aanpassen","Reclame maken","Vermaken"],"c":1,"d":2,"u":"Informatie wordt tegengehouden.","uo":["Dat is persvrijheid.","Klopt: informatie wordt tegengehouden.","Nee, het juiste antwoord is «Informatie tegenhouden of aanpassen».","Nee, het juiste antwoord is «Informatie tegenhouden of aanpassen»."],"uh":"Informatie wordt tegengehouden."},{"v":"Wat is beeldvorming?","o":["Een foto maken","Reclame","Het beeld dat media oproepen","Censuur"],"c":2,"d":2,"u":"Het beeld dat je van iets krijgt.","uo":["Nee, het juiste antwoord is «Het beeld dat media oproepen».","Nee, het juiste antwoord is «Het beeld dat media oproepen».","Klopt: het beeld dat je van iets krijgt.","Nee, het juiste antwoord is «Het beeld dat media oproepen»."],"uh":"Het beeld dat je van iets krijgt."},{"v":"Wat is nepnieuws?","o":["Onjuiste berichten als echt nieuws","Echt nieuws","Reclame","Een mening"],"c":0,"d":2,"u":"Onware berichten die als echt worden verspreid.","uo":["Klopt: onware berichten die als echt worden verspreid.","Nee, het juiste antwoord is «Onjuiste berichten als echt nieuws».","Nee, het juiste antwoord is «Onjuiste berichten als echt nieuws».","Nee, het juiste antwoord is «Onjuiste berichten als echt nieuws»."],"uh":"Onjuiste berichten als echt nieuws: Onware berichten die als echt worden verspreid."},{"v":"Wat is de opiniërende functie?","o":["Nieuws geven","Vermaken","Reclame maken","Meningen geven"],"c":3,"d":2,"u":"Meningen geven.","uo":["Dat is informeren.","Dat is amuseren.","Nee, het juiste antwoord is «Meningen geven».","Klopt: meningen geven."],"uh":"Meningen geven."},{"v":"Wat is objectiviteit?","o":["Bevooroordeeld schrijven","Onbevooroordeeld de feiten weergeven","Nepnieuws maken","Reclame"],"c":1,"d":3,"u":"Onbevooroordeeld weergeven.","uo":["Juist niet, het juiste antwoord is «Onbevooroordeeld de feiten weergeven».","Klopt: onbevooroordeeld weergeven.","Nee, het juiste antwoord is «Onbevooroordeeld de feiten weergeven».","Nee, het juiste antwoord is «Onbevooroordeeld de feiten weergeven»."],"uh":"Onbevooroordeeld weergeven."},{"v":"Wat is manipulatie?","o":["Feiten geven","Vermaken","Iemands mening bewust sturen","Vrij publiceren"],"c":2,"d":2,"u":"De mening bewust sturen.","uo":["Nee, het juiste antwoord is «Iemands mening bewust sturen».","Nee, het juiste antwoord is «Iemands mening bewust sturen».","Klopt: de mening bewust sturen.","Nee, het juiste antwoord is «Iemands mening bewust sturen»."],"uh":"Iemands mening bewust sturen: De mening bewust sturen."},{"v":"Wat zijn sociale media?","o":["Netwerken waarop mensen zelf berichten delen","Een krant","De televisie","Een reclamebord"],"c":0,"d":1,"u":"Online netwerken om zelf te delen.","uo":["Klopt: online netwerken om zelf te delen.","Nee, het juiste antwoord is «Netwerken waarop mensen zelf berichten delen».","Nee, het juiste antwoord is «Netwerken waarop mensen zelf berichten delen».","Nee, het juiste antwoord is «Netwerken waarop mensen zelf berichten delen»."],"uh":"Netwerken waarop mensen zelf berichten delen: Online netwerken om zelf te delen."}],"begrippen":[{"t":"Massamedia","d":"media die veel mensen tegelijk bereiken"},{"t":"Informerende functie","d":"het geven van nieuws en informatie"},{"t":"Amuserende functie","d":"het vermaken van het publiek"},{"t":"Opiniërende functie","d":"het geven van meningen"},{"t":"Beeldvorming","d":"het beeld dat media van iets of iemand oproepen"},{"t":"Manipulatie","d":"het bewust sturen van iemands mening"},{"t":"Censuur","d":"het tegenhouden of aanpassen van informatie"},{"t":"Persvrijheid","d":"het recht van media om vrij te publiceren"},{"t":"Objectiviteit","d":"het onbevooroordeeld weergeven van feiten"},{"t":"Reclame","d":"een boodschap om mensen tot kopen aan te zetten"},{"t":"Sociale media","d":"online netwerken waarop mensen zelf berichten delen"},{"t":"Nepnieuws","d":"onjuiste berichten die als echt nieuws worden verspreid"}],"sam":"<div class=\"sam-intro\"><strong>Massamedia</strong> bereiken veel mensen tegelijk en hebben een <strong>informerende</strong>, <strong>amuserende</strong> en <strong>opiniërende</strong> functie. Media bepalen mede de <strong>beeldvorming</strong>; <strong>persvrijheid</strong> beschermt het vrij publiceren.</div><div class=\"sam-head\">1. Functies van de media</div><p><strong>Massamedia</strong> zoals tv, kranten en nieuwssites bereiken veel mensen tegelijk. Ze hebben drie functies: de <strong>informerende functie</strong> (nieuws geven), de <strong>amuserende functie</strong> (vermaken) en de <strong>opiniërende functie</strong> (meningen geven). Op <strong>sociale media</strong> maken mensen bovendien zelf berichten.</p><div class=\"sam-head\">2. Beeldvorming en vrijheid</div><p>Media bepalen mede de <strong>beeldvorming</strong>: het beeld dat je van iets krijgt. Door <strong>manipulatie</strong> of <strong>nepnieuws</strong> kan dat beeld bewust worden gestuurd, terwijl <strong>objectiviteit</strong> juist onbevooroordeeld weergeven betekent. <strong>Persvrijheid</strong> geeft media het recht vrij te publiceren; het tegenovergestelde is <strong>censuur</strong>. <strong>Reclame</strong> wil je tot kopen aanzetten.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Massamedia</div><div class=\"sam-definitie-body\">media die veel mensen tegelijk bereiken.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Informerende functie</div><div class=\"sam-definitie-body\">het geven van nieuws en informatie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Amuserende functie</div><div class=\"sam-definitie-body\">het vermaken van het publiek.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Opiniërende functie</div><div class=\"sam-definitie-body\">het geven van meningen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Beeldvorming</div><div class=\"sam-definitie-body\">het beeld dat media van iets of iemand oproepen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Manipulatie</div><div class=\"sam-definitie-body\">het bewust sturen van iemands mening.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Censuur</div><div class=\"sam-definitie-body\">het tegenhouden of aanpassen van informatie.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Persvrijheid</div><div class=\"sam-definitie-body\">het recht van media om vrij te publiceren.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Objectiviteit</div><div class=\"sam-definitie-body\">het onbevooroordeeld weergeven van feiten.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Reclame</div><div class=\"sam-definitie-body\">een boodschap om mensen tot kopen aan te zetten.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Sociale media</div><div class=\"sam-definitie-body\">online netwerken waarop mensen zelf berichten delen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Nepnieuws</div><div class=\"sam-definitie-body\">onjuiste berichten die als echt nieuws worden verspreid.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Massamedia»</b> is bereiken velen tegelijk, terwijl <b>«Sociale media»</b> netwerken om te delen is. <b>«Informerende functie»</b> is nieuws geven, terwijl <b>«Amuserende functie»</b> het publiek vermaken is. <b>«Opiniërende functie»</b> is meningen geven, terwijl <b>«Informerende functie»</b> nieuws geven is. <b>«Beeldvorming»</b> is het opgeroepen beeld, terwijl <b>«Manipulatie»</b> mening bewust sturen is.</div>"},"F":{"sv":[{"v":"Wat is digitalisering?","o":["Minder internet gebruiken","Steeds meer via computers en internet","Een datalek","Een algoritme"],"c":1,"d":1,"u":"Steeds meer gaat digitaal.","uo":["Juist niet, het juiste antwoord is «Steeds meer via computers en internet».","Klopt: steeds meer gaat digitaal.","Nee, het juiste antwoord is «Steeds meer via computers en internet».","Nee, het juiste antwoord is «Steeds meer via computers en internet»."],"uh":"Steeds meer gaat digitaal."},{"v":"Wat is privacy?","o":["Alles delen","Reclame","Zelf bepalen wat anderen over je weten","Een datalek"],"c":2,"d":2,"u":"Controle over je eigen gegevens.","uo":["Juist niet, het juiste antwoord is «Zelf bepalen wat anderen over je weten».","Nee, het juiste antwoord is «Zelf bepalen wat anderen over je weten».","Klopt: controle over je eigen gegevens.","Nee, het juiste antwoord is «Zelf bepalen wat anderen over je weten»."],"uh":"Zelf bepalen wat anderen over je weten: Controle over je eigen gegevens."},{"v":"Wat is een datalek?","o":["Persoonsgegevens komen per ongeluk vrij","Een veilige opslag","Een algoritme","Een filterbubbel"],"c":0,"d":2,"u":"Gegevens komen ongewild naar buiten.","uo":["Klopt: gegevens komen ongewild naar buiten.","Juist het tegenovergestelde.","Nee, het juiste antwoord is «Persoonsgegevens komen per ongeluk vrij».","Nee, het juiste antwoord is «Persoonsgegevens komen per ongeluk vrij»."],"uh":"Persoonsgegevens komen per ongeluk vrij: Gegevens komen ongewild naar buiten."},{"v":"Wat is een filterbubbel?","o":["Alles zien","Een datalek","Een virus","Alleen informatie zien die bij je past"],"c":3,"d":3,"u":"Je ziet vooral wat bij je past.","uo":["Juist niet, het juiste antwoord is «Alleen informatie zien die bij je past».","Nee, het juiste antwoord is «Alleen informatie zien die bij je past».","Nee, het juiste antwoord is «Alleen informatie zien die bij je past».","Klopt: je ziet vooral wat bij je past."],"uh":"Alleen informatie zien die bij je past: Je ziet vooral wat bij je past."},{"v":"Wat is een algoritme?","o":["Een virus","Regels waarmee een computer keuzes maakt","Een datalek","Een netwerk"],"c":1,"d":2,"u":"Rekenregels die keuzes maken.","uo":["Nee, het juiste antwoord is «Regels waarmee een computer keuzes maakt».","Klopt: rekenregels die keuzes maken.","Nee, het juiste antwoord is «Regels waarmee een computer keuzes maakt».","Nee, het juiste antwoord is «Regels waarmee een computer keuzes maakt»."],"uh":"Regels waarmee een computer keuzes maakt: Rekenregels die keuzes maken."},{"v":"Wat is cybercriminaliteit?","o":["Een filterbubbel","Een algoritme","Criminaliteit via internet","Een datalek"],"c":2,"d":2,"u":"Misdaad via computers en internet.","uo":["Nee, het juiste antwoord is «Criminaliteit via internet».","Nee, het juiste antwoord is «Criminaliteit via internet».","Klopt: misdaad via computers en internet.","Nee, het juiste antwoord is «Criminaliteit via internet»."],"uh":"Criminaliteit via internet: Misdaad via computers en internet."},{"v":"Wat zijn persoonsgegevens?","o":["Informatie die over een persoon gaat","Een algoritme","Reclame","Een netwerk"],"c":0,"d":1,"u":"Gegevens die over een persoon gaan.","uo":["Klopt: gegevens die over een persoon gaan.","Nee, het juiste antwoord is «Informatie die over een persoon gaat».","Nee, het juiste antwoord is «Informatie die over een persoon gaat».","Nee, het juiste antwoord is «Informatie die over een persoon gaat»."],"uh":"Informatie die over een persoon gaat: Gegevens die over een persoon gaan."},{"v":"Wat is de digitale kloof?","o":["Een datalek","Een virus","Een filterbubbel","Het verschil tussen wie wel en niet met techniek overweg kan"],"c":3,"d":3,"u":"Verschil in digitale vaardigheid.","uo":["Nee, het juiste antwoord is «Het verschil tussen wie wel en niet met techniek overweg kan».","Nee, het juiste antwoord is «Het verschil tussen wie wel en niet met techniek overweg kan».","Nee, het juiste antwoord is «Het verschil tussen wie wel en niet met techniek overweg kan».","Klopt: verschil in digitale vaardigheid."],"uh":"Het verschil tussen wie wel en niet met techniek overweg kan: Verschil in digitale vaardigheid."},{"v":"Waarvoor heb je vaak toestemming nodig?","o":["Om te ademen","Voor het gebruik van je persoonsgegevens","Om te lopen","Om te lezen"],"c":1,"d":2,"u":"Gegevens mogen vaak alleen met toestemming gebruikt worden.","uo":["Nee, het juiste antwoord is «Voor het gebruik van je persoonsgegevens».","Klopt: gegevens mogen vaak alleen met toestemming gebruikt worden.","Nee, het juiste antwoord is «Voor het gebruik van je persoonsgegevens».","Nee, het juiste antwoord is «Voor het gebruik van je persoonsgegevens»."],"uh":"Voor het gebruik van je persoonsgegevens: Gegevens mogen vaak alleen met toestemming gebruikt worden."},{"v":"Wat beschermt het auteursrecht?","o":["Je wachtwoord","Een netwerk","Het werk van een maker","Een algoritme"],"c":2,"d":2,"u":"Het werk van makers.","uo":["Nee, het juiste antwoord is «Het werk van een maker».","Nee, het juiste antwoord is «Het werk van een maker».","Klopt: het werk van makers.","Nee, het juiste antwoord is «Het werk van een maker»."],"uh":"Het werk van makers."},{"v":"Wat is anonimiteit?","o":["Onbekend blijven","Bekend zijn","Een datalek","Een algoritme"],"c":0,"d":1,"u":"Je identiteit blijft onbekend.","uo":["Klopt: je identiteit blijft onbekend.","Juist het tegenovergestelde.","Nee, het juiste antwoord is «Onbekend blijven».","Nee, het juiste antwoord is «Onbekend blijven»."],"uh":"Onbekend blijven: Je identiteit blijft onbekend."}],"begrippen":[{"t":"Digitalisering","d":"het steeds meer gebruiken van computers en internet"},{"t":"Privacy","d":"het recht om zelf te bepalen wat anderen over je weten"},{"t":"Sociale media","d":"online netwerken om berichten te delen"},{"t":"Persoonsgegevens","d":"informatie die over een persoon gaat"},{"t":"Datalek","d":"het per ongeluk vrijkomen van persoonsgegevens"},{"t":"Algoritme","d":"een set regels waarmee een computer keuzes maakt"},{"t":"Digitale kloof","d":"het verschil tussen wie wel en niet met techniek overweg kan"},{"t":"Cybercriminaliteit","d":"criminaliteit via computers en internet"},{"t":"Anonimiteit","d":"het onbekend blijven van je identiteit"},{"t":"Filterbubbel","d":"het alleen zien van informatie die bij je past"},{"t":"Auteursrecht","d":"het recht van een maker op zijn eigen werk"},{"t":"Toestemming","d":"het akkoord geven voor het gebruik van je gegevens"}],"sam":"<div class=\"sam-intro\"><strong>Digitalisering</strong> verandert de samenleving. <strong>Sociale media</strong> en <strong>algoritmes</strong> bepalen wat je ziet. <strong>Privacy</strong> en <strong>persoonsgegevens</strong> komen onder druk, bijvoorbeeld door een <strong>datalek</strong> of <strong>cybercriminaliteit</strong>.</div><div class=\"sam-head\">1. Digitalisering en privacy</div><p><strong>Digitalisering</strong> betekent dat steeds meer via computers en internet gaat. Daarbij is <strong>privacy</strong> belangrijk: het recht om zelf te bepalen wat anderen over je weten. Bedrijven verwerken <strong>persoonsgegevens</strong>, maar mogen dat vaak alleen met jouw <strong>toestemming</strong>. Het <strong>auteursrecht</strong> beschermt het werk van makers.</p><div class=\"sam-head\">2. Risico's online</div><p>Online zijn er ook risico's. Bij een <strong>datalek</strong> komen persoonsgegevens per ongeluk vrij; <strong>cybercriminaliteit</strong> is misdaad via internet. Een <strong>algoritme</strong> bepaalt wat je te zien krijgt, waardoor je in een <strong>filterbubbel</strong> terecht kunt komen: je ziet vooral wat bij je past. <strong>Anonimiteit</strong> maakt mensen soms brutaler, en niet iedereen kan even goed met techniek overweg: de <strong>digitale kloof</strong>.</p><div class=\"sam-head\">Begrippen op een rij</div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Digitalisering</div><div class=\"sam-definitie-body\">het steeds meer gebruiken van computers en internet.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Privacy</div><div class=\"sam-definitie-body\">het recht om zelf te bepalen wat anderen over je weten.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Sociale media</div><div class=\"sam-definitie-body\">online netwerken om berichten te delen.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Persoonsgegevens</div><div class=\"sam-definitie-body\">informatie die over een persoon gaat.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Datalek</div><div class=\"sam-definitie-body\">het per ongeluk vrijkomen van persoonsgegevens.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Algoritme</div><div class=\"sam-definitie-body\">een set regels waarmee een computer keuzes maakt.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Digitale kloof</div><div class=\"sam-definitie-body\">het verschil tussen wie wel en niet met techniek overweg kan.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Cybercriminaliteit</div><div class=\"sam-definitie-body\">criminaliteit via computers en internet.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Anonimiteit</div><div class=\"sam-definitie-body\">het onbekend blijven van je identiteit.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Filterbubbel</div><div class=\"sam-definitie-body\">het alleen zien van informatie die bij je past.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Auteursrecht</div><div class=\"sam-definitie-body\">het recht van een maker op zijn eigen werk.</div></div><div class=\"sam-definitie\"><div class=\"sam-definitie-term\">Toestemming</div><div class=\"sam-definitie-body\">het akkoord geven voor het gebruik van je gegevens.</div></div><div class=\"sam-onthoud\"><b>Let op de verschillen.</b> <b>«Digitalisering»</b> is meer computers en internet, terwijl <b>«Digitale kloof»</b> kloof in digitale kennis is. <b>«Privacy»</b> is controle over je gegevens, terwijl <b>«Persoonsgegevens»</b> informatie over een persoon is. <b>«Sociale media»</b> is netwerken om te delen, terwijl <b>«Filterbubbel»</b> alleen wat bij je past is. <b>«Datalek»</b> is gegevens komen vrij, terwijl <b>«Cybercriminaliteit»</b> misdaad via internet is.</div>"}});